/* @author MILO-GAO(高振銘)@2020 */ package page2020.core;import java.util.ArrayList;import java.util.List;import org.slf4j.Logger;import org.slf4j.LoggerFactory;import org.springframework.util.StringUtils;import page2020.anno.Data2020;import page2020.util.EmptyUtil;import page2020.view.B4;import page2020.view.H5;import page2020.view.bs4.B4button.Outline;import page2020.view.bs4.B4element;import page2020.view.bs4.B4show.D;public class DataTable extends B4element {	private static Logger log = LoggerFactory.getLogger(DataTable.class);	public static final String argument = "argument";	private static final String arg = "arg";	public class PagingType {		public static final String numbers = "numbers";		public static final String simple = "simple";		public static final String simpleNumbers = "simple_numbers";		public static final String full = "full";		public static final String fullNumbers = "full_numbers";		public static final String firstLastNumbers = "first_last_numbers";	}	public class DataButton {		public static final String all = "all";		public static final String colvis = "colvis";		public static final String copy = "copy";		public static final String print = "print";		public static final String csv = "csv";		public static final String excel = "excel";	}	private boolean buttonsJS = false;	private boolean fixedColumnsJS = false;	private boolean paging;	private boolean ordering;	private boolean info;	private String order;	private String targets;	private String orderData;	private String searchable;	private String visible;	private boolean domLength;	private boolean domFilter;	private boolean domInfo;	private boolean domPaging;	private String buttons;	private String fixedColumns;	private boolean stateSave;	private String pagingType;	private boolean scrollX;	private String scrollY;	private String lengthMenu;	private int displayLength;	private String langEmptyTable;	private String langInfo;	private String langInfoEmpty;	private String langInfoFiltered;	private String langInfoPostFix;	private String langLengthMenu;	private String langLoadingRecords;	private String langProcessing;	private String langSearch;	private String langZeroRecords;	private String langFirst;	private String langLast;	private String langNext;	private String langPrevious;	private boolean process = false;	private boolean proxy = false;	private int proxyLength = 0;	private boolean server = false;	public DataTable(String name, Data2020 anno) {		super();		super.name(name).cssClass(argument, D.none);		this.paging = anno.paging();		this.ordering = anno.ordering();		this.info = anno.info();		this.order = anno.order();		this.targets = anno.targets();		this.orderData = anno.orderData();		this.searchable = anno.searchable();		this.visible = anno.visible();		this.domLength = anno.domLength();		this.domFilter = anno.domFilter();		this.domInfo = anno.domInfo();		this.domPaging = anno.domPaging();		this.buttons = anno.buttons();		this.fixedColumns = anno.fixedColumns();		this.stateSave = anno.stateSave();		this.pagingType = anno.pagingType();		this.scrollX = anno.scrollX();		this.scrollY = anno.scrollY();		this.lengthMenu = anno.lengthMenu();		this.displayLength = anno.displayLength();		this.langEmptyTable = anno.langEmptyTable();		this.langInfo = anno.langInfo();		this.langInfoEmpty = anno.langInfoEmpty();		this.langInfoFiltered = anno.langInfoFiltered();		this.langInfoPostFix = anno.langInfoPostFix();		this.langLengthMenu = anno.langLengthMenu();		this.langLoadingRecords = anno.langLoadingRecords();		this.langProcessing = anno.langProcessing();		this.langSearch = anno.langSearch();		this.langZeroRecords = anno.langZeroRecords();		this.langFirst = anno.langFirst();		this.langLast = anno.langLast();		this.langNext = anno.langNext();		this.langPrevious = anno.langPrevious();		if (Log.table) {			log.info("DataTable('" + super.getName() + "')");		}	}	public DataTable automate() {		this.buttonsJS = EmptyUtil.not(this.buttons);		this.fixedColumnsJS = EmptyUtil.not(this.fixedColumns);		this.language();		super.data("paging", this.paging)			.data("ordering", this.ordering)			.data("info", this.info)			.data("order", this.order)			.data("targets", this.targets)			.data("order-data", this.orderData)			.data("searchable", this.searchable)			.data("visible", this.visible)			.data("dom", this.dom())			.data("buttons", this.buttons)			.data("fixed-columns", this.fixedColumns)			.data("state-save", this.stateSave)			.data("paging-type", this.pagingType)			.data("scroll-x", this.scrollX)			.data("scroll-y", this.scrollY)			.data("length-menu", this.lengthMenu)			.data("display-length", this.displayLength)			.data("process", this.process)			.append(				B4.element().append(					H5.span().data(arg, "emptyTable").code(this.langEmptyTable),					H5.span().data(arg, "info").code(this.langInfo),					H5.span().data(arg, "infoEmpty").code(this.langInfoEmpty),					H5.span().data(arg, "infoFiltered").code(this.langInfoFiltered),					H5.span().data(arg, "infoPostFix").code(this.langInfoPostFix),					H5.span().data(arg, "lengthMenu").code(this.langLengthMenu),					H5.span().data(arg, "loadingRecords").code(this.langLoadingRecords),					H5.span().data(arg, "processing").code(this.langProcessing),					H5.span().data(arg, "search").code(this.langSearch),					H5.span().data(arg, "zeroRecords").code(this.langZeroRecords),					H5.span().data(arg, "paginate").append(						H5.span().data(arg, "first").code(this.langFirst),						H5.span().data(arg, "last").code(this.langLast),						H5.span().data(arg, "next").code(this.langNext),						H5.span().data(arg, "previous").code(this.langPrevious)					)				),				B4.element()					.data("proxy", this.proxy)					.data("server", this.server),				this.dataButtons()			);		if (Log.table) {			log.info(String.format("DataTable('%s'): automate()", super.getName()));		}		return this;	}	public DataTable paging(boolean paging) {		this.paging = paging;		return this;	}	public DataTable ordering(boolean ordering) {		this.ordering = ordering;		return this;	}	public DataTable info(boolean info) {		this.info = info;		return this;	}	public DataTable order(String order) {		this.order = order.trim();		return this;	}	public DataTable targets(String targets) {		this.targets = targets;		return this;	}	public DataTable orderData(String orderData) {		this.orderData = orderData;		return this;	}	public DataTable searchable(Boolean... searchables) {		this.searchable = StringUtils.arrayToCommaDelimitedString(searchables);		return this;	}	public DataTable visible(Boolean... visibles) {		this.visible = StringUtils.arrayToCommaDelimitedString(visibles);		return this;	}	public DataTable domLength(boolean component) {		this.domLength = component;		return this;	}	public DataTable domFilter(boolean component) {		this.domFilter = component;		return this;	}	public DataTable domInfo(boolean component) {		this.domInfo = component;		return this;	}	public DataTable domPaging(boolean component) {		this.domPaging = component;		return this;	}	public DataTable buttons(String... buttons) {		if (EmptyUtil.not(buttons)) {			if (buttons.length == 1) {				this.buttons = buttons[0].trim();			} else {				this.buttons = StringUtils.arrayToCommaDelimitedString(buttons);			}		}		return this;	}	public DataTable fixedColumns(int left, int right) {		if (left >= 0 || right >= 0) {			this.fixedColumns = String.format("%d,%d", left, right);		} else {			this.fixedColumns = "";		}		return this;	}	public DataTable stateSave(boolean stateSave) {		this.stateSave = stateSave;		return this;	}	public DataTable pagingType(String pagingType) {		this.pagingType = pagingType;		return this;	}	public DataTable scrollX(boolean scrollX) {		this.scrollX = scrollX;		return this;	}	public DataTable scrollY(String pixels) {		this.scrollY = pixels;		return this;	}	public DataTable lengthMenu(String items) {		this.lengthMenu = items;		return this;	}	public DataTable displayLength(int number) {		this.displayLength = number;		return this;	}	public DataTable langEmptyTable(String code) {		this.langEmptyTable = code;		return this;	}	public DataTable langInfo(String code) {		this.langInfo = code;		return this;	}	public DataTable langInfoEmpty(String code) {		this.langInfoEmpty = code;		return this;	}	public DataTable langInfoFiltered(String code) {		this.langInfoFiltered = code;		return this;	}	public DataTable langInfoPostFix(String code) {		this.langInfoPostFix = code;		return this;	}	public DataTable langLengthMenu(String code) {		this.langLengthMenu = code;		return this;	}	public DataTable langLoadingRecords(String code) {		this.langLoadingRecords = code;		return this;	}	public DataTable langProcessing(String code) {		this.langProcessing = code;		return this;	}	public DataTable langSearch(String code) {		this.langSearch = code;		return this;	}	public DataTable langZeroRecords(String code) {		this.langZeroRecords = code;		return this;	}	public DataTable langFirst(String code) {		this.langFirst = code;		return this;	}	public DataTable langLast(String code) {		this.langLast = code;		return this;	}	public DataTable langNext(String code) {		this.langNext = code;		return this;	}	public DataTable langPrevious(String code) {		this.langPrevious = code;		return this;	}	public void serial() {		if (EmptyUtil.is(this.fixedColumns)) {			this.fixedColumns = "1,0";		} else {			String[] tokens = this.fixedColumns.split(",");			int left = Integer.valueOf(tokens[0].trim()).intValue() + 1;			this.fixedColumns = String.format("%d,%s", left, tokens[1].trim());		}	}	public DataTable process(boolean process) {		this.process = true;		this.proxy = false;		this.proxyLength = 0;		this.server = false;		return this;	}	public DataTable proxy(int length) {		this.process = true;		this.proxy = true;		this.proxyLength = (length >= 0) ? length : 0;		this.server = false;		return this;	}	@Override	public DataTable copy() {		return (DataTable) super.copy();	}	private String dom() {		List<String> args = new ArrayList<String>();		if (this.domLength) {			args.add("length");		}		if (this.domFilter) {			args.add("filter");		}		if (this.domInfo) {			args.add("info");		}		if (this.domPaging) {			args.add("paging");		}		if (EmptyUtil.not(this.buttons)) {			args.add("buttons");		}		if (! args.isEmpty()) {			return StringUtils.collectionToCommaDelimitedString(args);		} else {			return "";		}	}	private void language() {		if (EmptyUtil.is(this.langEmptyTable)) {			this.langEmptyTable = "page2020.datatable.emptyTable";		}		if (EmptyUtil.is(this.langInfo)) {			this.langInfo = "page2020.datatable.info";		}		if (EmptyUtil.is(this.langInfoEmpty)) {			this.langInfoEmpty = "page2020.datatable.infoEmpty";		}		if (EmptyUtil.is(this.langInfoFiltered)) {			this.langInfoFiltered = "page2020.datatable.infoFiltered";			}		if (EmptyUtil.is(this.langInfoPostFix)) {			this.langInfoPostFix = "page2020.datatable.infoPostFix";		}		if (EmptyUtil.is(this.langLengthMenu)) {			this.langLengthMenu = "page2020.datatable.lengthMenu";		}		if (EmptyUtil.is(this.langLoadingRecords)) {			this.langLoadingRecords = "page2020.datatable.loadingRecords";		}		if (EmptyUtil.is(this.langProcessing)) {			this.langProcessing = "page2020.datatable.processing";			}		if (EmptyUtil.is(this.langSearch)) {			this.langSearch = "page2020.datatable.search";			}		if (EmptyUtil.is(this.langZeroRecords)) {			this.langZeroRecords = "page2020.datatable.zeroRecords";			}		if (EmptyUtil.is(this.langFirst)) {			this.langFirst = "page2020.datatable.paginate.first";			}		if (EmptyUtil.is(this.langLast)) {			this.langLast = "page2020.datatable.paginate.last";			}		if (EmptyUtil.is(this.langNext)) {			this.langNext = "page2020.datatable.paginate.next";			}		if (EmptyUtil.is(this.langPrevious)) {			this.langPrevious = "page2020.datatable.paginate.previous";		}	}	private B4element dataButtons() {		B4element element = B4.element();		String buttons = this.buttons;		if (buttons.contains(DataButton.all)) {			List<String> buffer = new ArrayList<String>();			buffer.add(DataButton.colvis);			buffer.add(DataButton.copy);			buffer.add(DataButton.print);			buffer.add(DataButton.csv);			buffer.add(DataButton.excel);			buttons = StringUtils.collectionToCommaDelimitedString(buffer);		}		if (buttons.contains(DataButton.colvis)) {			element.append(				B4.button(Outline.info).data(arg, DataButton.colvis)					.append(App.icon("datatable.colvis"), H5.span().code("page2020.datatable.colvis")));		}		if (buttons.contains(DataButton.copy)) {			element.append(				B4.button(Outline.info).data(arg, DataButton.copy)					.append(App.icon("datatable.copy"), H5.span().code("page2020.datatable.copy")));		}		if (buttons.contains(DataButton.print)) {			element.append(				B4.button(Outline.info).data(arg, DataButton.print)					.append(App.icon("datatable.print"), H5.span().code("page2020.datatable.print")));		}		if (buttons.contains(DataButton.csv)) {			element.append(				B4.button(Outline.primary).data(arg, DataButton.csv)					.append(App.icon("datatable.csv"), H5.span().code("page2020.datatable.csv")));		}		if (buttons.contains(DataButton.excel)) {			element.append(				B4.button(Outline.primary).data(arg, DataButton.excel)					.append(App.icon("datatable.excel"), H5.span().code("page2020.datatable.excel")));		}		return element;	}	public boolean isButtonsJS() {		return buttonsJS;	}	public boolean isFixedColumnsJS() {		return fixedColumnsJS;	}	public boolean isProcess() {		return process;	}	public boolean isProxy() {		return proxy;	}	public int getProxyLength() {		return proxyLength;	}	public boolean isServer() {		return server;	}}